import React from 'react';
import { Link } from 'react-router-dom';

import Logo from '../assets/logo.png';
// css link
import '../styles/register.css';
function Register() {
  // Handle Submit
  const handleSubmit = (e) => {
    e.preventDefault();
    alert('form');
  };
  // Handle Change
  const handleChange = (e) => {};
  // Return
  return (
    <div id="register_component">
      <form onSubmit={(e) => handleSubmit(e)}>
        {/* Logo and title */}
        <div className="logo">
          <img src={Logo} alt="Brand Logo" />
          <h2>chaxapp</h2>
        </div>
        {/* User div */}
        <div className="input_div">
          <input
            type="text"
            name="username"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>username</label>
          <div className="error_div">input error</div>
        </div>
        {/* Mobile number div */}
        <div className="input_div">
          <input
            type="text"
            name="mobileNumber"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>Mobile number</label>
          <div className="error_div">mobile error</div>
        </div>
        {/* Password div */}
        <div className="input_div">
          <input
            type="password"
            name="password"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>Password</label>
          <div className="error_div">passwor error</div>
        </div>
        {/* Confirm Password div */}
        <div className="input_div">
          <input
            className='error'
            type="password"
            name="confirmPassword"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>Confirm Password</label>
          <div className="error_div">confirm password</div>
        </div>
        {/* Register buttom */}
        <button type="submit">Create account</button>
        {/* hrd */}
        <div className="or">
          <span></span>
          <p>or</p>
          <span></span>
        </div>
        {/* login */}
        <div className="login_div">
          <p>Already have an account ?</p>
          <Link to="/login">sign in</Link>
        </div>
      </form>
    </div>
  );
}

export default Register;
